"""Ready-made stage functions."""


def rename(mapping):
    def apply(rec):
        return {mapping.get(k, k): v for k, v in rec.items()}

    return apply


def select(fields):
    fields = list(fields)

    def apply(rec):
        return {f: rec[f] for f in fields if f in rec}

    return apply


def cast(field, kind):
    convert = {"int": int, "float": float, "str": str}[kind]

    def apply(rec):
        out = dict(rec)
        out[field] = convert(rec[field])
        return out

    return apply

def require(fields):
    fields = list(fields)

    def apply(rec):
        for f in fields:
            if rec.get(f) is None:
                raise ValueError(f"missing field: {f}")
        return rec

    return apply

